226	  const wanted = new Set(plan.flatMap((p) => p.records));
227	  const specs = (await loadMigrations()).filter((m) => wanted.has(m.dir));
228	  const exists = (p) => existsSync(join(targetRoot, p));
229	  const read = (p) => (existsSync(join(targetRoot, p)) ? readFileSync(join(targetRoot, p), 'utf8') : null);
230	
231	  const put = (p, c) => { mkdirSync(dirname(join(targetRoot, p)), { recursive: true }); writeFileSync(join(targetRoot, p), c); };
232	
233	  // A path under `.github/workflows/` is REFUSED, not diverted. The flow's caller
234	  // pushes with the Action's GITHUB_TOKEN, which GitHub never lets write there, and the
235	  // refusal rejects the whole ref — so writing one would fail the entire update rather
236	  // than deliver a file. Nothing needs to: a member's workflows are static after
237	  // adoption (#1317). A record that materializes one is reported skipped, which is what
238	  // the absent `CLAUDINITE_CAN_WITHHOLD_WORKFLOWS` handshake tells its `appliesTo`.
239	  const write = (p, c) => { if (!p.startsWith(WORKFLOW_DIR)) put(p, c); };
240	  const move = (from, to) => { mkdirSync(dirname(join(targetRoot, to)), { recursive: true }); renameSync(join(targetRoot, from), join(targetRoot, to)); };
241	  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);
242	  const io = { exists, move, read, write, readTemplate, env: {} };
243	  const applied = [];
244	  for (const m of specs) applied.push(...(await applyMigration(m, io)));
245	
246	  // 2c. THE CLAUDE.md PACK INDEX (#807), for the same reason as 2b and at the same
247	  //     point: its content is a function of the pack set, and the vendor above is
248	  //     what just changed it. The engine flow converges the index too, but it runs
249	  //     BEFORE the packs in a cycle — so on the one night a pack lands, the engine
250	  //     flow's copy is already yesterday's, and without this the member would carry
251	  //     a stale index (and inject the whole corpus through the hook as a fallback)
252	  //     until some later cycle happened to touch the engine.
253	  //
254	  //     Written straight to the tree rather than withheld: the index is not a
255	  //     workflow path, so no credential refuses it.
256	  const { writeRulesIndex, RULES_INDEX_FILE } = await import('../../../engine/pack_loader/generate-rules-index.mjs');
257	  const { ensureRulesIndexImport, ensureRulesIndexMergeAttribute } = await import('../../../engine/converge-wiring.mjs');
258	  if (await writeRulesIndex(targetRoot)) applied.push(`converged ${RULES_INDEX_FILE}`);
259	  if (ensureRulesIndexImport(targetRoot)) applied.push('added the CLAUDE.md pack-index import');
260	  if (ensureRulesIndexMergeAttribute(targetRoot)) applied.push('declared merge=ours for the pack index');
261	
262	  // …and sweep the retired staging directory. A member that converged before #1317 may
263	  // still carry files the withhold lane staged; nothing is owed now, so every one of
264	  // them goes. The sweep is also how a member confirms the lane is gone — the directory
265	  // is empty exactly when nothing is outstanding, and it stays that way.
266	  for (const stale of stagedFiles(targetRoot)) rmSync(join(targetRoot, stale), { force: true });
267	
268	  // 3. Stamp each updated pack's version. Written per pack rather than wholesale, so
269	  //    a pack this run did not touch keeps the number it really has.
270	  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
271	  // Only what this run moved: a version lands on the entry of the pack it prices,
272	  // and a pack this run did not touch keeps the number it really has. The old
273	  // spelling of a renamed pack cannot be carried forward here even by accident —
274	  // there is no map to carry it in, only entries the declaration itself names
275	  // (#1041 is what a second key in a central map cost).
276	  const packVersions = {};
277	  for (const p of plan) if (p.to !== null) packVersions[p.id] = p.to;
278	  writeFileSync(settingsFile, `${JSON.stringify(withInstalledVersions(next, { packVersions }), null, 2)}\n`);
