280	  // 4. The same gate the engine flow uses, then the agentic tail's own question —
281	  //    ASKED OF THE RECORDS, NOT OF THE VERSION PLAN (#798).
282	  //
283	  //    This used to be `moved.length > 0`: any declared pack whose version number
284	  //    changed summoned a session. That is a fact about the CANON, and the stage
285	  //    exists for a fact about the MEMBER — the pack's new rules met content the
286	  //    canon has never seen. The two coincide only by accident.
287	  //
288	  //    The cost of conflating them was not theoretical. A record can only reach an
289	  //    up-to-date member if its pack's manifest version bumps (`migrationApplies` is
290	  //    `want > have` against the stamped number, and the stamp written is the
291	  //    manifest's). So every mechanical migration — a regex rewrite, a rename, a
292	  //    declaration seed, all deterministic and idempotent — had to buy a session on
293	  //    every member in the fleet to reach them at all. Deterministic work priced as
294	  //    agentic work is how a fleet learns to dread its own updates.
295	  //
296	  //    So the records answer. Each one's author knew which kind they were writing,
297	  //    and `applyStage` is where they say so. A bump carrying no such record is
298	  //    silent, which is what makes a first live run of an agentic change something
299	  //    you can aim at one member instead of fourteen at once.
300	  const selftest = runSelfTest(targetRoot, selfTestRun);
301	  const decision = deliveryDecision({ selftestOk: selftest.ok, delivery, forceMergeOnRedCi });
302	  // A wiring failure rides out on `detail`, which the worker already prints and which
303	  // becomes the PR body and the work item's reason. Appended rather than given a
304	  // field of its own, because a new field only reaches a member when its worker
305	  // catches up a cycle later, and `detail` reaches every fielded worker today.
306	  // No flow computes a workflow any more, so there is no wiring failure left to ride
307	  // out on `detail`. The field stays null rather than absent: a fielded worker reads it,
308	  // and a key that vanished would read as a worker too old to report one.
309	  const wiringError = null;
310	  const detail = decision.why;
311	  const withheld = [];
312	
313	  return outcome(decision.action === 'needs-human' ? NEEDS_HUMAN : 'ok', detail, {
314	    plan, files: packFiles.length, applied, selftest, decision, withheld,
315	    wiringError, applyStage: applyStageFor(specs, withheld),
316	  });
